def can_form_palindrome(s):
    # Create a count array to store count of characters
    count = [0]*256  # Assuming ASCII characters

    # Calculate count of characters
    for i in s:
        count[ord(i)] += 1

    # Count odd occurring characters
    odd = 0
    for i in range(256):
        if (count[i] & 1):
            odd += 1

        if odd > 1:
            return False

    # Return true if odd count is 0 or 1
    return True

def can_be_palindrome(s):
    # Get the length of input string
    n = len(s)

    # If length of string is 0 or 1, it can be converted into palindrome
    if n==0 or n==1:
        return True

    # Find a character in string which is not palindrome.
    for i in range(0, int(n/2)):
        if s[i] != s[n-1-i]:
            break

    # Now check if removing this character makes string palindrome.
    # If removal of character makes the string palindrome, return true.
    return can_form_palindrome(s[i+1: n-i-1])

