    """

    scores = {
        "attention_to_detail": 0,
        "precision": 0,
        "technical_knowledge": 0,
        "problem_solving_skills": 0,
    }

    weights = {
        "attention_to_detail": 0.3,
        "precision": 0.3,
        "technical_knowledge": 0.2,
        "problem_solving_skills": 0.2,
    }

    score_categories = scores.keys()

    for category in score_categories:
